import json
import itertools

def main():
    # Input variables (trip constraints)
    total_days = 20
    city_durations = {
        "Hamburg": 7,
        "Munich": 6,
        "Manchester": 2,
        "Lyon": 2,
        "Split": 7,
    }
    must_be_in_windows = {
        "Lyon": (13, 14),
        "Manchester": (19, 20),
    }
    cities = list(city_durations.keys())

    # Directed flight graph (direct flights only)
    edges = set()
    def add_undirected(a, b):
        edges.add((a, b))
        edges.add((b, a))
    def add_direct(a, b):
        edges.add((a, b))

    # Add edges based on constraints
    add_undirected("Split", "Munich")
    add_undirected("Munich", "Manchester")
    add_undirected("Hamburg", "Manchester")
    add_undirected("Hamburg", "Munich")
    add_undirected("Split", "Lyon")
    add_undirected("Lyon", "Munich")
    add_undirected("Hamburg", "Split")
    add_direct("Manchester", "Split")  # one-way

    # Helper: compute city day ranges with overlap on flight days
    def compute_ranges(order):
        ranges = {}
        prev_end = None
        for i, city in enumerate(order):
            L = city_durations[city]
            if i == 0:
                start = 1
                end = start + L - 1
            else:
                start = prev_end  # overlap on flight day
                end = start + L - 1
            ranges[city] = (start, end)
            prev_end = end
        return ranges

    # Helper: validate direct path
    def is_direct_path(order):
        for a, b in zip(order, order[1:]):
            if (a, b) not in edges:
                return False
        return True

    # Helper: validate windows and total days logic
    def satisfies_constraints(order, ranges):
        # Window constraints
        for city, (req_start, req_end) in must_be_in_windows.items():
            if ranges[city] != (req_start, req_end):
                return False
        # Total unique days must be exactly total_days
        itinerary_end = max(end for _, end in ranges.items())
        if itinerary_end != total_days:
            return False
        # Sum of city-days must equal total_days + number_of_flights
        sum_city_days = sum(city_durations[c] for c in order)
        num_flights = len(order) - 1
        if sum_city_days != total_days + num_flights:
            return False
        return True

    feasible_itinerary = None

    # Search all permutations for a feasible, optimal (fewest flights) itinerary
    # With 5 unique cities, fewest flights to visit all is 4 (which is fixed here).
    for order in itertools.permutations(cities):
        # Quick pruning: Manchester must end at day 20 with a 2-day window (days 19-20),
        # thus it must be the last city in the order.
        if order[-1] != "Manchester":
            continue
        # Quick pruning: Lyon must be days 13-14; to make start at 13 with the overlap model,
        # the first two city durations must sum to 14 (with durations [7,7])
        # So Lyon must be third, and first two must be the two 7-day cities in some order.
        if "Lyon" not in order or order.index("Lyon") != 2:
            continue
        first_two = order[:2]
        if sorted(first_two) != sorted([c for c, d in city_durations.items() if d == 7]):
            continue
        # Path must be direct
        if not is_direct_path(order):
            continue
        ranges = compute_ranges(order)
        if satisfies_constraints(order, ranges):
            feasible_itinerary = [(city, ranges[city]) for city in order]
            break

    if feasible_itinerary is None:
        raise RuntimeError("No feasible itinerary found with given constraints.")

    # Build JSON output
    output = {
        "itinerary": [
            {
                "day_range": f"Day {start}-{end}",
                "place": city
            }
            for city, (start, end) in feasible_itinerary
        ]
    }
    print(json.dumps(output, ensure_ascii=False))

if __name__ == "__main__":
    main()
